theorem updBor_eq (s : St) :
    s.borrowState.block ≤ s.blockNumber →
    updateCompBorrowIndex s = some { s with borrowState := accrueSide s.borrowState s.blockNumber (totalBorrows s) }

theorem updSup_eq (s : St) :
    s.supplyState.block ≤ s.blockNumber →
    updateCompSupplyIndex s = some { s with supplyState := accrueSide s.supplyState s.blockNumber (totalSupply s) }

theorem setBor_char (s : St) (b : Nat) (s2 : St) (h : setBorrowSpeed s b = some s2) :
    (s.borrowState.speed ≠ b → s.borrowState.block ≤ s.blockNumber) ∧
    s2 = { s with borrowState := if s.borrowState.speed = b then s.borrowState else { accrueSide s.borrowState s.blockNumber (totalBorrows s) with speed := b } }

theorem setSup_char (s : St) (a : Nat) (s1 : St) (h : setSupplySpeed s a = some s1) :
    (s.supplyState.speed ≠ a → s.supplyState.block ≤ s.blockNumber) ∧
    s1 = { s with supplyState := if s.supplyState.speed = a then s.supplyState else { accrueSide s.supplyState s.blockNumber (totalSupply s) with speed := a } }
